    @push('scripts')<script>function opnameForm(products){return {products,filter:'',selected:[],actual:{},get filteredProducts(){const value=this.filter.toLowerCase();return this.products.filter(product=>!value||product.name.toLowerCase().includes(value)||product.code.toLowerCase().includes(value))},get selectedProducts(){return this.products.filter(product=>this.selected.includes(String(product.id))||this.selected.includes(product.id))},selectAll(){this.selected=this.products.map(product=>product.id)},clearAll(){this.selected=[]},difference(product){const value=Number(this.actual[product.id]);return (Number.isNaN(value)?0:value)-Number(product.stock)}}}</script>@endpush
